class AdjMSELoss(nn.Module):

    def __init__(self):
        super(AdjMSELoss, self).__init__()

    def forward(self, outputs, labels):
        loss = torch.abs(outputs - labels)
        adj_fact = torch.mean(torch.abs(labels)) ** 2
