class KLLoss(nn.Module):

    def forward(self, mu: 'torch.Tensor', sigma: 'torch.Tensor', target_mu:
        'torch.Tensor', target_std: 'torch.Tensor'):
        std1 = target_std
        std2 = sigma
        mean1 = target_mu
        mean2 = mu
        kl = torch.log(torch.abs(std2) / torch.abs(std1)) + (std1 ** 2 + (
