class ConditionalEntropyLoss(torch.nn.Module):

    def __init__(self, model):
        super(ConditionalEntropyLoss, self).__init__()

    def forward(self, x, weight):
        loss = F.softmax(x, dim=1) * F.log_softmax(x, dim=1) * weight
